import{_ as t,o,c as d,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"티켓이 지나는 상태","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/states"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/states"}],["meta",{"property":"og:title","content":"티켓이 지나는 상태"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/states.md","filePath":"docs/states.md"}'),c={name:"docs/states.md"};function a(n,e,s,i,p,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="티켓이-지나는-상태" tabindex="-1">티켓이 지나는 상태 <a class="header-anchor" href="#티켓이-지나는-상태" aria-label="Permalink to &quot;티켓이 지나는 상태&quot;">​</a></h1><p>보드의 레인은 셋입니다. 대기 · 진행중 · 완료. 그 셋이 파일 셋과 정확히 짝지어져 있습니다. 카드를 끌어 옮기는 손잡이가 없는 이유가 이것입니다. 레인은 사람이 정하는 칸이 아니라 <strong>파일명 접미사를 그린 것</strong>이니까요.</p><table tabindex="0"><thead><tr><th>보드 레인</th><th>파일</th><th>뜻</th></tr></thead><tbody><tr><td>대기</td><td><code>&lt;해시&gt;.md</code></td><td>열려 있고, 다음 tick의 후보입니다</td></tr><tr><td>진행중</td><td><code>&lt;해시&gt;.wip.md</code></td><td>누군가 잡았습니다</td></tr><tr><td>완료</td><td><code>&lt;해시&gt;.done.md</code></td><td>끝났습니다</td></tr></tbody></table><p>상태는 이 셋이 전부입니다. 워커가 티켓을 집으면 파일 이름이 <code>.wip</code>을 얻고 카드가 오른쪽 레인으로 넘어갑니다. 세션이 끝나며 <code>.done</code>으로 바꾸면 한 칸 더 갑니다. 앱은 그 파일을 읽어 그릴 뿐, 상태를 만들지는 않습니다.</p><p>접미사 문자열 자체는 워커 설정에서 바꿀 수 있습니다(기본값 <code>.wip</code>·<code>.done</code>). 어떤 문자열을 쓰든 판정 방식은 같습니다. 그 파일 이름이 그 문자열로 끝나는지만 봅니다.</p><h2 id="레인에-없는-표시-둘" tabindex="-1">레인에 없는 표시 둘 <a class="header-anchor" href="#레인에-없는-표시-둘" aria-label="Permalink to &quot;레인에 없는 표시 둘&quot;">​</a></h2><p>레인은 티켓이 지나가는 단계를 그립니다. 그런데 <code>대기</code>에 앉아 있는 티켓 중에는 순서가 와도 넘어가지 못하는 것이 있습니다. 단계가 하나 더 있는 게 아니라 그 단계 안의 사정이라서, 레인을 넷으로 늘리는 대신 카드에 표시를 붙여 말합니다.</p><p><strong><code>deps 대기</code> — 주황색 <code>deps</code> 태그.</strong> 선행 티켓이 아직 안 끝났다는 뜻입니다. 카드에 미충족 해시가 주황색으로 뜨고, 그 티켓은 <code>대기</code> 레인 제자리에 그대로 앉아 있습니다. 막혔다고 아래로 밀지 않습니다. 밀어 버리면 위쪽 카드가 &quot;곧 디스패치&quot;라는 거짓말이 되기 때문입니다. <strong>사람이 할 일은 없습니다.</strong> 선행이 완료되는 순간 아무도 손대지 않아도 태그가 사라지고 그 티켓이 후보가 됩니다.</p><p><strong><code>답변 대기</code> — 배지와 경과일(<code>답변 대기 · 3일</code>).</strong> 세션이 사람에게 물어보고 손을 뗀 상태입니다. 그 티켓은 답이 파일로 생길 때까지 잠겨 있어서 아무 워커도 집어 가지 않습니다. 같은 질문에 세션을 반복해서 태우지 않으려고 걸어 둔 잠금입니다. 티켓 상세를 열면 질문 아래에 답을 쓰는 칸이 있습니다. 답을 쓰면 앱이 <code>kind: answer</code> 파일을 하나 만들고, 그 파일이 태어나는 순간 잠금이 풀리며 배지가 <code>대기</code>로 돌아갑니다.</p><p>경과일이 배지에 같이 붙는 것은 방치를 눈에 보이게 하려는 것입니다. 자동 만료도 자동 취소도 없습니다. 오래된 <code>답변 대기</code>가 정체의 신호이고, 그것을 판단하는 것은 사람입니다.</p><p>둘 다 보드 상태 필터의 선택지로도 있습니다. 필터 선택지는 여섯인데 레인은 셋이고, 그게 정상입니다. 필터는 엔진이 아는 상태를 고르는 자리고, 레인은 흐름의 단계를 그리는 자리니까요.</p><h2 id="디스패치되지-않는-티켓" tabindex="-1">디스패치되지 않는 티켓 <a class="header-anchor" href="#디스패치되지-않는-티켓" aria-label="Permalink to &quot;디스패치되지 않는 티켓&quot;">​</a></h2><p>열려 있는데 아무 워커도 집지 않는 티켓의 사유는 셋입니다. 위 둘, 그러니까 <code>deps 대기</code>와 <code>답변 대기</code>는 <strong>정상입니다.</strong> 밖의 조건이 풀리면 저절로 열립니다.</p><p>셋째만 사고입니다. <strong>열린 파일에 <code>session_id</code>가 박혀 있는 경우</strong>(배지 이름은 <code>할당됨</code>)인데, 이 조합을 엔진은 만들지 않습니다. 사람이 파일에 <code>session_id</code>를 손으로 적었거나, 그 값이 든 티켓을 통째로 베껴 새 티켓으로 만들었을 때 생깁니다. 그러면 이렇게 됩니다.</p><ul><li>후보를 고르는 쪽은 <code>session_id</code>가 있으면 이미 할당됐다고 보고 영구히 건너뜁니다.</li><li>죽은 세션을 회수하는 쪽은 <code>.wip</code>만 봅니다. 이 티켓은 <code>.wip</code>이 아니니 회수 대상도 아닙니다.</li></ul><p>집히지도 회수되지도 않고 조용히 죽습니다. 배지 하나로는 그 화면을 열지 않는 한 영원히 모르기 때문에, 앱은 이것을 <strong>헤더 알림 종 안의 항목</strong>으로 올립니다. <code>아무도 집지 않는 티켓 &lt;n&gt;건</code>.</p><ul><li>프로젝트 화면 어디에 있든 보입니다. 보드에만 두면 워커 화면을 보고 있는 사람은 모릅니다.</li><li>필터로 끌 수 없고, 상위 몇 건으로 자르지도 않습니다. 해당 티켓 전부를 나열하고, 행마다 <code>할당 해제</code> 버튼이 붙습니다. 그 버튼이 하는 일은 <code>session_id</code>를 지우는 것 하나입니다.</li><li>닫기도 읽음 표시도 없습니다. 5초마다 다시 판정하므로 0건이 되면 항목이 저절로 사라집니다. &quot;해결됨&quot;을 앱이 따로 기록하지는 않습니다. 기록하는 순간 파일의 사실과 갈릴 수 있는 두 번째 진실이 생기기 때문입니다.</li></ul><p>이 티켓들은 칸반 어느 레인에도 없습니다. 그래서 보드의 <code>티켓 N건</code> 합계가 레인 합계보다 클 수 있고, 그 자리에 <code>(디스패치되지 않는 N건은 상단 알림)</code>이 같이 적혀 있습니다.</p><p><code>session_id</code>를 비롯해 디스패처와 엔진이 쓰는 키는 사람이 채우는 값이 아닙니다. 어떤 키가 있고 누가 언제 쓰는지는 <a href="/docs/ref-frontmatter">frontmatter 필드</a>에 표로 있습니다.</p><h2 id="파일명이-곧-락인-이유" tabindex="-1">파일명이 곧 락인 이유 <a class="header-anchor" href="#파일명이-곧-락인-이유" aria-label="Permalink to &quot;파일명이 곧 락인 이유&quot;">​</a></h2><p>상태를 frontmatter가 아니라 파일명에 둔 이유는 하나입니다. <strong>이름을 바꾸는 동작 자체가 락이라서</strong> 워커 여럿이 같은 큐를 봐도 충돌이 없습니다.</p><p>잡기(claim)는 <code>os.link</code>로 <code>&lt;해시&gt;.wip.md</code>를 만들고 원본을 지우는 동작입니다. 목적지가 이미 있으면 커널이 <code>EEXIST</code>를 돌려줍니다. 이미 잡혔다는 뜻입니다. <strong>판정(&quot;아직 안 잡혔나&quot;)과 획득(&quot;내가 잡는다&quot;)이 한 시스템콜 안에 있어서</strong> 그 사이에 다른 프로세스가 끼어들 틈이 없습니다. 동시에 같은 티켓을 본 워커 여섯 중 먼저 링크에 성공한 하나만 이기고, 나머지는 다음 후보로 넘어갑니다. 새로 발명한 계보는 아닙니다. 메일 하나를 <code>new/</code>에서 <code>cur/</code>로 옮기는 rename을 락으로 쓰는 <a href="https://en.wikipedia.org/wiki/Maildir" target="_blank" rel="noreferrer">Maildir</a>와 같습니다.</p><p>하드링크를 지원하지 않는 파일시스템(구글드라이브 같은 FUSE·SMB 마운트)에서는 <code>O_CREAT|O_EXCL</code>로 폴백합니다. 이것도 원자적 배타 생성이라 같은 성질을 유지합니다. 상태를 frontmatter로 옮기면 값을 읽고 고쳐 쓰는 사이가 프로세스 간에 원자적이지 않아, 파일명이 공짜로 주던 락을 따로 사야 합니다.</p><p>다음은 <a href="/docs/worker">워커</a>입니다.</p>',24)])])}const m=t(c,[["render",a]]);export{g as __pageData,m as default};
